const links=document.querySelector('.nav-links');
if(links&&!links.querySelector('a[href="/blog/"]')){const quote=links.querySelector('.btn');const blog=document.createElement('a');blog.href='/blog/';blog.textContent='Blog';if(location.pathname.startsWith('/blog')||location.pathname.startsWith('/resources'))blog.className='active';links.insertBefore(blog,quote)}
const menu=document.querySelector('.menu-toggle');menu?.addEventListener('click',()=>{const open=links.classList.toggle('open');menu.setAttribute('aria-expanded',open)});
document.querySelectorAll('.footer').forEach(footer=>{if(footer.children.length)return;footer.innerHTML=`<div class="shell"><div class="footer-grid footer-complete"><div class="footer-intro"><a class="brand" href="/"><img loading="lazy" decoding="async" width="160" height="240" src="/assets/logo-mark.webp" alt=""><span>Featherbleu Industries<small>Live smarter. Be safer.</small></span></a><p>Professional security and automation solutions for homes and businesses. Live smarter. Be safer.</p></div><div><h4>Quick links</h4><div class="footer-links"><a href="/">Home</a><a href="/services/">Services</a><a href="/projects/">Projects</a><a href="/about/">About Us</a><a href="/contact/">Contact</a></div></div><div><h4>Our services</h4><div class="footer-links"><a href="/services/smart-home-automation/">Smart Home Automation</a><a href="/services/garage-doors/">Garage Doors</a><a href="/services/gate-automation/">Gate Automation</a><a href="/services/cctv/">CCTV Systems</a><a href="/services/access-control/">Access Control</a></div></div><div><h4>Resources</h4><div class="footer-links"><a href="/blog/">Blog</a><a href="/resources/security-tips/">Security Tips</a><a href="/resources/installation-guides/">Installation Guides</a><a href="/resources/maintenance-advice/">Maintenance Advice</a><a href="/resources/industry-news/">Industry News</a></div></div></div><div class="footer-bottom"><span>© 2026 Featherbleu Industries. All rights reserved.</span><span><a href="https://www.pixaloom.co.za">Built by Pixaloom</a> · Live Smarter. Be Safer.</span></div></div>`});
document.querySelectorAll('.gallery-item[data-full]').forEach(item=>item.addEventListener('click',()=>{const box=document.querySelector('.lightbox');box.querySelector('img').src=item.dataset.full||item.querySelector('img').src;box.querySelector('img').alt=item.querySelector('img').alt;box.classList.add('open')}));document.querySelector('.lightbox-close')?.addEventListener('click',()=>document.querySelector('.lightbox').classList.remove('open'));document.querySelector('.lightbox')?.addEventListener('click',e=>{if(e.target.classList.contains('lightbox'))e.currentTarget.classList.remove('open')});document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('.lightbox')?.classList.remove('open')});

// Contact intent only: a click does not confirm that an enquiry was sent or a call answered.
document.addEventListener('click',event=>{
 const anchor=event.target.closest?.('a[href]');if(!anchor||typeof window.gtag!=='function')return;
 const href=anchor.getAttribute('href');const method=href.startsWith('tel:')?'phone':href.startsWith('mailto:')?'email':href.startsWith('https://wa.me/')?'whatsapp':null;if(!method)return;
 const recipient=href.includes('27829217299')?'werner':href.includes('27645120021')?'joe':'general';
 const placement=anchor.dataset.contactPlacement||(anchor.closest('.hero-actions')?'hero':anchor.closest('.cta')?'page-end':anchor.closest('.contact-panel')?'contact-card':anchor.classList.contains('whatsapp')?'floating':anchor.closest('.footer')?'footer':'content');
 const slug=location.pathname.split('/')[2];const services=['gate-automation','garage-doors','cctv','access-control','smart-home-automation'];
 const service=location.pathname==='/'?'home':location.pathname==='/services/'?'all-services':location.pathname.startsWith('/services/')&&services.includes(slug)?slug:'other';
 window.gtag('event','contact_click',{contact_method:method,contact_recipient:recipient,contact_placement:placement,service_page:service});
});
